  --runtime-instance-id 'local-authority:local-authority-f06b17af-2b12-4b51-8e75-49506e084910' \\
  --workspace-id 'workspace-44c2b737-ada8-4e45-b8d9-1d30aadf4fdc' \\
  --document-id 'document-1b633407-6552-4f35-a64b-7ac3899a306d' \\
  --content-document-id 'document-1b633407-6552-4f35-a64b-7ac3899a306d' \\
  --page-id '0:2688' \\
  --request-id 'portfolio-brief-page-0-2688-20260730-v1' \\
  --intent 'Build a polished editable board brief for allocating a two million dollar ocean-cleanup portfolio across three programs, with comparable impact, cost, execution risk, recommended mix, decision rules, and three first-week actions.' \\
  --plan-file - --json <<'JSON'
{
  \"contract\": \"board-build-plan/v1\",
  \"artifacts\": [
    {
      \"alias\": \"title\",
      \"recipe\": {
        \"kind\": \"native_text\",
        \"text\": \"OCEAN IMPACT PORTFOLIO  |  "'$2M ALLOCATION BRIEF",
        "placement": { "target": { "kind": "auto" } }
      }
    },
    {
      "alias": "recommendation",
      "recipe": {
        "kind": "native_card",
        "title": "Decision at a glance",
        "body": "RECOMMENDED MIX'"\\n"'$900k River Interception  •  45%'"\\n"'$700k Ghost Gear Recovery  •  35%'"\\n"'$400k Coastal Circularity  •  20%'"\\n\\nFund each line in gated 60% / 40% tranches.\"
      }
    },
    {
      \"alias\": \"portfolio_outcome\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Modeled 12-month outcome\",
        \"body\": \"2,550–4,350 t removed or prevented\\nBlended "'$460–$785 per verified tonne'"\\nHigher habitat benefit than a tonnage-only portfolio\\n\\nPlanning ranges, not guarantees. Ghost-gear tonnes carry disproportionate habitat value.\"
      }
    },
    {
      \"alias\": \"decision_rules\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Explicit decision rules\",
        \"body\": \"1  Fund only with baseline, permits, named operator, and chain of custody.\\n2  Release final 40% at day 90 only if pace is ≥70% of target and safeguards pass.\\n3  Reallocate after two reviews if forecast cost/t is >25% above the range midpoint.\\n4  Pause on serious safety events, illegal disposal, unverifiable weights, or unresolved community grievance.\"
      }
    },
    {
      \"alias\": \"river_program\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Program 1  |  River Interception\",
        \"body\": \"WHAT IT DOES\\nIntercepts plastic at high-leakage river mouths before ocean entry.\\n\\nIMPACT  1,800–3,000 t/year\\nCOST  "'$300–$500 / verified t'"\\nEXECUTION RISK  MEDIUM\\n\\nStrongest measurement case. Watch permits, flood-season uptime, and downstream processing.\"
      }
    },
    {
      \"alias\": \"ghost_program\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Program 2  |  Ghost Gear Recovery\",
        \"body\": \"WHAT IT DOES\\nRetrieves abandoned fishing gear with ports and fishers; verifies recycling or disposal.\\n\\nIMPACT  250–450 t/year\\nCOST  "'$1,550–$2,800 / verified t'"\\nEXECUTION RISK  MED-HIGH\\n\\nHigh ecological benefit per tonne. Watch weather windows, vessel safety, and chain of custody.\"
      }
    },
    {
      \"alias\": \"coastal_program\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Program 3  |  Coastal Circularity\",
        \"body\": \"WHAT IT DOES\\nFunds local collection, reuse, and leakage prevention around coastal hotspots.\\n\\nIMPACT  500–900 t/year\\nCOST  "'$445–$800 / verified t'"\\nEXECUTION RISK  HIGH\\n\\nBest local-ownership upside. Watch partner capacity, double counting, and weak baselines.\"
      }
    },
    {
      \"alias\": \"river_allocation\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \""'$900k  |  Anchor on measurable scale",
        "body": "WHY 45%'"\\nMost measurable and scalable option in the portfolio.\\n\\nUSE OF FUNDS\\n2–3 interception sites; operations; verified sorting and disposal.\\n\\nBOARD DEBATE\\nOne proven operator—or split across two basins?\"
      }
    },
    {
      \"alias\": \"ghost_allocation\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \""'$700k  |  Buy ecological leverage",
        "body": "WHY 35%'"\\nProtect habitat where tonnage alone understates value.\\n\\nUSE OF FUNDS\\nPriority removals; port logistics; fisher incentives; gear traceability.\\n\\nBOARD DEBATE\\nShould habitat-risk scoring outweigh cost per tonne?\"
      }
    },
    {
      \"alias\": \"coastal_allocation\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \""'$400k  |  Preserve prevention upside",
        "body": "WHY 20%'"\\nKeep a prevention and community-capacity option without overexposing the portfolio.\\n\\nUSE OF FUNDS\\n4–6 milestone grants; local audits; reuse or offtake pilots.\\n\\nBOARD DEBATE\\nWhat evidence is sufficient before scaling?\"
      }
    },
    {
      \"alias\": \"week_action_1\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Day 1–2  |  Lock the scorecard\",
        \"body\": \"OWNER  COO + Impact lead\\n\\nApprove definitions for verified tonnes, habitat risk, cost per tonne, downtime, safety incidents, and community grievances.\\n\\nOUTPUT  One shared investment scorecard.\"
      }
    },
    {
      \"alias\": \"week_action_2\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Day 3–4  |  Send term sheets\",
        \"body\": \"OWNER  Programs lead\\n\\nSend one-page terms to shortlisted operators covering baselines, budget, permits, chain of custody, quarterly targets, and stop conditions.\\n\\nOUTPUT  Comparable offers.\"
      }
    },
    {
      \"alias\": \"week_action_3\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Day 5–7  |  Make the tranche call\",
        \"body\": \"OWNER  Board chair + Finance\\n\\nRun a 90-minute red-team review. Approve 60% initial tranches only for gate-ready programs and schedule the day-90 release decision.\\n\\nOUTPUT  Signed allocation memo.\"
      }
    }
  ],
  \"connections\": [],
  \"layout\": {
    \"kind\": \"grid\",
    \"anchor\": { \"alias\": \"title\" },
    \"members\": [
      \"recommendation\",
      \"portfolio_outcome\",
      \"decision_rules\",
      \"river_program\",
      \"ghost_program\",
      \"coastal_program\",
      \"river_allocation\",
      \"ghost_allocation\",
      \"coastal_allocation\",
      \"week_action_1\",
      \"week_action_2\",
      \"week_action_3\"
    ],
    \"columns\": 3,
    \"column_gap\": 56,
    \"row_gap\": 48,
    \"align\": \"start\",
    \"placement\": {
      \"clearance\": 80,
      \"preferred_directions\": [\"below\"]
    }
  }
}
JSON"

